export const MODULE = 'therapist-session'
export const LISTING_URL = ({therapy_center_id, therapist_id}) => {return {path: `therapist-session/index_list?therapy_center_id=${therapy_center_id}&therapist_id=${therapist_id}`, method: 'GET'}}
export const STORE_URL = () => {return {path: `${MODULE}`, method: 'POST'}}
export const EDIT_URL = (id) => {return {path: `${MODULE}/${id}/edit`, method: 'GET'}}
export const THERAPY_CENTER_LIST = (id) => {return {path: `therapy-centers/index_list?therapist_id=${id}`, method: 'GET'}}

export const THERAPIST_DATA = (id) => {return {path: `therapist/${id}/edit`, method: 'GET'}}
export const THERAPIST_LIST = (id) => {return {path: `therapist/index_list`, method: 'GET'}}

export const THERAPY_CENTER_SESSION_LIST = (id) => {return {path: `therapy-center-session/index_list?therapy_center_id=${id}`, method: 'GET'}}
