            <div class="form-group col-md-6" v-if="enable_multi_vendor && (role() === 'admin' || role() === 'demo_admin')">
              <label class="form-label" for="vendor_id">{{ $t('sidebar.vendors') }} <span class="text-danger">*</span> </label>
