            <div class="col-md-6 form-group">
              <label class="form-label" for="therapy_center">{{ $t('therapy.lbl_select_therapy_center') }}</label><span class="text-danger">*</span>
              <Multiselect id="therapy_center_id" v-model="therapy_center_id" :value="therapy_center_id" :multiple="true" placeholder="Select Therapy Center"
