            <InputField class="col-md-6" :label="$t('therapy.lbl_expert')" placeholder="" v-model="expert"
              :error-message="errors['expert']" :error-messages="errorMessages['expert']"></InputField>
            <InputField class="col-md-6" :label="$t('therapy.lbl_facebook_link')" placeholder="" v-model="facebook_link"
