              <Vue3Signature ref="signature" :w="'300px'" :h="'50px'" style="border: 1px solid #8a92a6" class="example"></Vue3Signature>
              <button @click="clear">Clear</button>
            </div>
              
              <InputField class="col-md-6" :label="$t('therapy.lbl_lat')" placeholder="" v-model="latitude" :error-message="errors['latitude']"
                  :error-messages="errorMessages['latitude']"></InputField>
              <InputField class="col-md-6" :label="$t('therapy.lbl_long')" placeholder="" v-model="longitude" :error-message="errors['longitude']" 
                  :error-messages="errorMessages['longitude']"></InputField>


              <InputField class="col-md-6" :label="$t('therapy.experience')" placeholder="" v-model="experience" :error-message="errors['experience']" 
                  :error-messages="errorMessages['experience']"></InputField>


              <!-- qualification detail-->
              <legend>{{$t('therapy.qualification')}}</legend>
              <div class="row">
                <div class="col-md-12" v-for="(input, index) in userInputList" :key="index">
                  <div class="row">
                    <div class="form-group col-md-4">
                      <label class="form-label" for="degree">{{ $t('therapy.degree') }}</label>
                      <input type="text" class="form-control" :placeholder="$t('therapy.degree')" v-model="input.degree"  id="degree" />
                      <span class="text-danger degree_err" :id="`degree_err_${index}`"></span>
                    </div>

                    <div class="form-group col-md-4">
                      <label class="form-label" for="university">{{ $t('therapy.university') }}</label>
                      <input type="text" class="form-control" :placeholder="$t('therapy.university')" v-model="input.university"  id="university" />
                      <span class="text-danger university_err" :id="`university_err_${index}`"></span>
                    </div>
                    
                    <div class="form-group col-md-4">
                        <label class="form-label" for="year">{{ $t('therapy.year') }}</label>
                        <multiselect v-model="input.year" :placeholder="$t('therapy.year')" :options="yearRange()" v-bind="singleSelectOption" id="year"></multiselect>
                        <span class="text-danger year_err" :id="`year_err_${index}`"></span>
                    </div>

                    <div class="row" v-if="userInputList.length>1">
                      <div class="form-group col-12 text-end">
                        <button type="button" @click="removeQualification(index)" class="btn btn-danger px-3"><i class="fa-regular fa-trash-can"></i></button>
                      </div>
                      <div class="col-12">
                        <div class="border-top mt-3 pb-5"></div>
                      </div>
                    </div>

                  </div>
                </div>
                
                <div class="form-group col-md-12 text-end">
                  <a @click="addQualification" class="btn btn-primary">
                    <i class="fa-solid fa-plus"></i> {{$t('therapy.add_qualification')}}
                  </a>
                </div>
              </div>


              <div class="form-group mb-0 col-md-12">
                <div class="d-flex justify-content-between align-items-center">
                  <label class="form-label mb-0" for="category-status">{{ $t('therapy.lbl_status') }}</label>
                  <div class="form-check form-switch">
                    <input class="form-check-input" :value="1" name="status" id="category-status" type="checkbox"
