<template>
    <form @submit="formSubmit">
        <div class="offcanvas offcanvas-end" tabindex="-1" id="form-offcanvas" aria-labelledby="form-offcanvasLabel">
            <FormHeader :currentId="currentId" :editTitle="editTitle" :createTitle="createTitle"></FormHeader>
            <div class="offcanvas-body">
                <div class="form-group">
                    <div class="text-center">
                        <img :src="ImageViewer || defaultImage" alt="feature-image" class="img-fluid mb-2 avatar-140 avatar-rounded" />
                        <div class="d-flex align-items-center justify-content-center gap-2">
                            <input type="file" ref="profileInputRef" class="form-control d-none" id="file_url" name="file_url" @change="fileUpload" accept=".jpeg, .jpg, .png, .gif" />
                            <label class="btn btn-info" for="file_url">{{ $t('messages.upload') }}</label>
                            <input type="button" class="btn btn-danger" name="remove" :value="$t('messages.remove')" @click="removeLogo()" v-if="ImageViewer" />
                        </div>
                    </div>
                </div>
                <InputField class="col-md-12" type="text" :is-required="true" :label="$t('service_package.lbl_name')" placeholder="" v-model="name" :error-message="errors['name']" :error-messages="errorMessages['name']"></InputField>
                <InputField class="col-md-12" type="text" :is-required="true" :label="$t('service.lbl_duration_min')" placeholder="" v-model="duration_min" :error-message="errors['duration_min']" :error-messages="errorMessages['duration_min']"></InputField>
                <InputField class="col-md-12" type="text" :is-required="true" :label="`${$t('service.lbl_default_price')} (${CURRENCY_SYMBOL})`" placeholder="" v-model="charges" :error-message="errors['charges']" :error-messages="errorMessages['charges']"></InputField>

                <div class="form-group" v-if="enable_multi_vendor && (role() === 'admin' || role() === 'demo_admin')">
                    <label class="form-label" for="vendor_id">{{ $t('sidebar.vendors') }} <span class="text-danger">*</span> </label>
                    <Multiselect class="form-group" v-model="vendor_id" :value="vendor_id" :options="vendors.options"  v-bind="singleSelectOption" @select="getCategoryList" placeholder="Select Vendor" id="vendor_id"></Multiselect>
                    <span v-if="errorMessages['vendor_id']">
                        <ul class="text-danger">
                        <li v-for="err in errorMessages['vendor_id']" :key="err">{{ err }}</li>
                        </ul>
                    </span>
                    <span class="text-danger">{{ errors.vendor_id }}</span>
                </div>

                <div class="form-group">
                    <label class="form-label" for="category_id">{{ $t('service.lbl_category') }} <span class="text-danger">*</span> </label>
                    <Multiselect v-model="category_id" :value="category_id" v-bind="categories" id="category_id" @select="changeCategory"></Multiselect>
                    <span v-if="errorMessages['category_id']">
                        <ul class="text-danger">
                            <li v-for="err in errorMessages['category_id']" :key="err">{{ err }}</li>
                        </ul>
                    </span>
                    <span class="text-danger">{{ errors.category_id }}</span>
                </div>

                <!-- <div class="form-group" v-if="subCategories.options.length > 0">
          <label class="form-label" for="sub_category_id">{{ $t('service.lbl_sub_category') }} </label>
          <Multiselect v-model="sub_category_id" :value="sub_category_id" v-bind="subCategories" id="sub_category_id"></Multiselect>
          <span v-if="errorMessages['sub_category_id']">
            <ul class="text-danger">
              <li v-for="err in errorMessages['sub_category_id']" :key="err">{{ err }}</li>
            </ul>
          </span>
          <span class="text-danger">{{ errors.sub_category_id }}</span>
        </div> -->

                <div v-for="field in customefield" :key="field.id">
                    <FormElement v-model="custom_fields_data" :name="field.name" :label="field.label" :type="field.type" :required="field.required" :options="field.value" :field_id="field.id"></FormElement>
                </div>

                <div class="form-group col-md-12">
                    <div class="form-group">
                        <label class="form-label" for="therapy_center_id">{{ $t('therapy.singular_title') }} <span class="text-danger">*</span></label>
                        <Multiselect id="therapy_center_id" v-model="therapy_center_id" :multiple="true" :value="therapy_center_id" :placeholder="$t('therapy.singular_title')" v-bind="multiSelectOption" :options="therapy_centers.options" class="form-group"> </Multiselect>
                        <span v-if="errorMessages['therapy_center_id']">
                            <ul class="text-danger">
                                <li v-for="err in errorMessages['therapy_center_id']" :key="err">{{ err }}</li>
                            </ul>
                        </span>
                        <span class="text-danger">{{ errors.therapy_center_id }}</span>
                    </div>
                </div>

                <div class="form-group col-md-12">
                    <label class="form-label" for="description">{{ $t('service.lbl_description') }}</label>
                    <textarea class="form-control" v-model="description" id="description"></textarea>
                    <span v-if="errorMessages['description']">
                        <ul class="text-danger">
                            <li v-for="err in errorMessages['description']" :key="err">{{ err }}</li>
                        </ul>
                    </span>
                    <span class="text-danger">{{ errors.description }}</span>
                </div>

                <div class="form-group">
                    <div class="d-flex justify-content-between align-items-center">
                        <label class="form-label" for="category-status">{{ $t('service.lbl_status') }}</label>
                        <div class="form-check form-switch">
                            <input class="form-check-input" :value="status" :checked="status" name="status" id="category-status" type="checkbox" v-model="status" />
                        </div>
                    </div>
                </div>
            </div>
            <FormFooter :IS_SUBMITED="IS_SUBMITED"></FormFooter>
        </div>
    </form>
</template>

<script setup>
import { ref, onMounted, computed} from 'vue'
import { EDIT_URL, STORE_URL, UPDATE_URL, CATEGORY_LIST, THERAPY_CENTER_LIST ,VENDOR_LIST,APP_CONFIGURATION} from '../constant/therapy-service'
import { useField, useForm } from 'vee-validate'
import InputField from '@/vue/components/form-elements/InputField.vue'
import { useSelect } from '@/helpers/hooks/useSelect'
import { useModuleId, useRequest, useOnOffcanvasHide } from '@/helpers/hooks/useCrudOpration'
import * as yup from 'yup'
import { buildMultiSelectObject } from '@/helpers/utilities'
import { readFile } from '@/helpers/utilities'
import FormHeader from '@/vue/components/form-elements/FormHeader.vue'
import FormFooter from '@/vue/components/form-elements/FormFooter.vue'
import FormElement from '@/helpers/custom-field/FormElement.vue'

// props
const props = defineProps({
    createTitle: { type: String, default: '' },
    editTitle: { type: String, default: '' },
    customefield: { type: Array, default: () => [] },
    defaultImage: { type: String, default: 'https://dummyimage.com/600x300/cfcfcf/000000.png' }
})

const role = () => {
    return window.auth_role[0];
}

const enable_multi_vendor = ref(false);
const getAppConfiguration = (() => {
  getRequest({ url: APP_CONFIGURATION }).then((res) => {
    if (res.status && res.enable_multi_vendor === 1) {
      enable_multi_vendor.value = true;
    } else {
      console.error('Error fetching configuration:');
    }})
})

const CURRENCY_SYMBOL = ref(window.defaultCurrencySymbol)
const { getRequest, storeRequest, updateRequest, listingRequest } = useRequest()
let selectedCenter = ref([]);
let selectedCategory = ref([]);
// Edit Form Or Create Form
const currentId = useModuleId(() => {
    subCategories.value.options = []
    if (currentId.value > 0) {
        getRequest({ url: EDIT_URL, id: currentId.value }).then((res) => {
            if (res.status) {
                setFormData(res.data)
                changeCategory(category_id.value)
                getCategoryList(vendor_id.value)
                selectedCenter.value = res.data.therapy_center_id || [];
                therapy_center_id.value = selectedCenter.value;
                selectedCategory.value = res.data.category_id || [];
                category_id.value = selectedCategory.value;
            }
        })
    } else {
        setFormData(defaultData())
    }
})
const multiSelectOption = ref({
    mode: 'tags',
    closeOnSelect: true,
    searchable: true
})
// File Upload Function
const ImageViewer = ref(null)
const profileInputRef = ref(null)
const fileUpload = async (e) => {
    let file = e.target.files[0]
    await readFile(file, (fileB64) => {
        ImageViewer.value = fileB64
        profileInputRef.value.value = ''
    })
    file_url.value = file
}

// Function to delete Images
const removeImage = ({ imageViewerBS64, changeFile }) => {
    imageViewerBS64.value = null
    changeFile.value = null
}

const removeLogo = () => removeImage({ imageViewerBS64: ImageViewer, changeFile: file_url })

/*
 * Form Data & Validation & Handeling
 */
// Default FORM DATA
const defaultData = () => {
    ImageViewer.value = props.defaultImage
    errorMessages.value = {}
    return {
        name: '',
        description: '',
        duration_min: '',
        charges: '',
        status: 1,
        vendor_id: '',
        category_id: '',
        // sub_category_id: '',
        file_url: null,
        therapy_center_id: [],
        custom_fields_data: {}
    }
}

//  Reset Form
const setFormData = (data) => {
    ImageViewer.value = data.file_url 
    resetForm({
        values: {
            name: data.name,
            description: data.description,
            duration_min: data.duration_min,
            charges: data.charges,
            status: data.status,
            vendor_id: data.vendor_id,
            category_id: data.category_id,
            // sub_category_id: data.sub_category_id,
            file_url: data.file_url,
            therapy_center_id: data.therapy_center_id,
            custom_fields_data: data.custom_field_data
        }
    })
}

// Reload Datatable, SnackBar Message, Alert, Offcanvas Close
const reset_datatable_close_offcanvas = (res) => {
    IS_SUBMITED.value = false
    if (res.status) {
        window.successSnackbar(res.message)
        renderedDataTable.ajax.reload(null, false)
        bootstrap.Offcanvas.getInstance('#form-offcanvas').hide()
        setFormData(defaultData())
        removeImage({ imageViewerBS64: ImageViewer, changeFile: file_url })
    } else {
        window.errorSnackbar(res.message)
        errorMessages.value = res.all_message
    }
}

const numberRegex = /^\d+$/
// Validations
const validationSchema = yup.object({
    name: yup.string().required('Name is a required field'),
    duration_min: yup.string().required('Service Duration ( Mins ) is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
    charges: yup.string().required('Charges is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
    category_id: yup.string().required('Category is a required field').matches(/^\d+$/, 'Only numbers are allowed'),
    description: yup.string().test('no-script-tags', 'The Description field cannot contain script tags.', function (value) {
        const scriptTagRegex = /<script\b[^>]*>(.*?)/is
        return !scriptTagRegex.test(value)
    }),
    therapy_center_id: yup.array().test('therapy_center_id', 'therapy center is a required field', function (value) {
    if (value.length == 0) {
      return false
    }
    return true
  })
})

const { handleSubmit, errors, resetForm } = useForm({
    validationSchema
})
const { value: name } = useField('name')
const { value: description } = useField('description')
const { value: duration_min } = useField('duration_min')
const { value: charges } = useField('charges')
const { value: status } = useField('status')
const { value: vendor_id } = useField('vendor_id')
const { value: category_id } = useField('category_id')
// const { value: sub_category_id } = useField('sub_category_id')
const { value: file_url } = useField('file_url')
const { value: therapy_center_id } = useField('therapy_center_id')
const { value: custom_fields_data } = useField('custom_fields_data')

const errorMessages = ref({})

const categories = ref({
    searchable: true,
    createOption: true,
    options: []
})

const subCategories = ref({
    searchable: true,
    createOption: true,
    options: []
})



const getCategoryList = (value) => {
    category_id.value = [];
    therapy_center_id.value=[];
    listingRequest({ url: CATEGORY_LIST, data: { id: 0, vendor_id: value } }).then((res) => (categories.value.options = buildMultiSelectObject(res, { value: 'id', label: 'name' })))
}

const changeCategory=(value)=>{

    therapy_center_id.value=[];

 useSelect({ url: THERAPY_CENTER_LIST, data: { id: value } }, { value: 'id', label: 'center_name' }).then((data) => (therapy_centers.value = data))

}

const therapy_centers = ref({ options: [], list: [] })


const vendors = ref({ options: [], list: [] })
const getVendorList = () => {
  useSelect({ url: VENDOR_LIST ,data: { system_service: 'therapy' }  }, { value: 'id', label: 'name' }).then((data) => (vendors.value = data))
  }

onMounted(() => {
    getCategoryList()
    getVendorList()
    getAppConfiguration()
    setFormData(defaultData())
})

// Form Submit
const IS_SUBMITED = ref(false)
const formSubmit = handleSubmit((values) => {
    if (IS_SUBMITED.value) return false

    values.custom_fields_data = JSON.stringify(values.custom_fields_data)
    if (currentId.value > 0) {
        updateRequest({ url: UPDATE_URL, id: currentId.value, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
    } else {
        storeRequest({ url: STORE_URL, body: values, type: 'file' }).then((res) => reset_datatable_close_offcanvas(res))
    }
})
</script>

