<template>
  <form @submit="formSubmit" class="bussiness-hour">
    <div class="offcanvas offcanvas-end" tabindex="-1" id="form-offcanvas" aria-labelledby="form-offcanvasLabel">
      <div class="offcanvas-header border-bottom" v-if="Therapist">
        <h6 class="m-0 h5">
          <span>{{ Title }}</span>
        </h6>
      </div>
      <div class="form-group" v-if="therapistlist.options.length > 0">
          <div class="form-group p-3">
            <label class="form-label">{{ $t('clinic.lbl_select_therapist') }}<span class="text-danger">*</span></label>
            <Multiselect id="therapist_id" v-model="therapist_id" :value="therapist_id" v-bind="singleSelectOption" :options="therapistlist.options" @select="TherapyCenterSelect" class="form-group"></Multiselect>
            <span class="text-danger">{{ errors.therapist_id }}</span>
          </div>
        </div>
      <div class="form-group col-md-12 row" v-if="therapy_center.options.length > 0">
        <div class="form-group p-3 col-md-6">
          <label class="form-label">{{ $t('therapy.lbl_center_name') }}<span class="text-danger">*</span></label>
          <Multiselect id="therapy_center_id" v-model="therapy_center_id" v-bind="singleSelectOption" :options="therapy_center.options" @select="TherapyCenterSelect" class="form-group"></Multiselect>
          <span class="text-danger">{{ errors.therapy_center_id }}</span>
        </div>
        <div class="form-group p-3 col-md-6">
          <label class="form-label">{{ $t('clinic.lbl_time_slot') }}<span class="text-danger">*</span></label>
          <Multiselect id="time_slot" v-model="time_slot" v-bind="singleSelectOption" :options="gettimeslot()" @input="setTimeSlots" class="form-group"></Multiselect>
          <span class="text-danger">{{ errors.time_slot }}</span>
        </div>
      </div>
      <ul class="data-scrollbar list-group list-group-flush">
        <li v-for="(day, index) in weekdays" class="form-group col-md-12 list-group-item" :key="++index">
          <div class="form-group col-md-12 gap-1">
            <h4 class="text-capitalize">{{ index }}. {{ day.day }} <i v-if="index === 1" class="fa fa-copy copy-icon" aria-hidden="true" @click="handleCopy"></i></h4>

            <div class="col-md-12 row row-cols-3">
              <flat-pickr id="start_time" class="form-control" v-model="day.start_time" :config="config" :disabled="day.is_holiday ? true : false" :class="{ background_colour: day.is_holiday }"></flat-pickr>
              <flat-pickr id="end_time" class="form-control" v-model="day.end_time" :config="config" :disabled="day.is_holiday ? true : false" :class="{ background_colour: day.is_holiday }"></flat-pickr>

              <div class="form-group">
                <div class="d-flex gap-1">
                  <div class="form-check">
                    <input class="form-check-input" :value="1" name="is_holiday" :id="`${index}-dayoff`" type="checkbox" :true-value="1" :false-value="0" v-model="day.is_holiday" :disabled="centerHolidays.includes(day.day)" />
                  </div>
                  <label class="form-label" :for="`${index}-dayoff`">{{ $t('therapy.lbl_add_day_off') }}</label>
                </div>
              </div>
              <div v-if="day.startTimeError" class="text-danger">{{ day.startTimeError }}</div>
              <div v-if="day.endTimeError" class="text-danger">{{ day.endTimeError }}</div>
            </div>
            <template v-if="!day.is_holiday">
              <div v-for="(input, index) in day.breaks" :key="index" class="form-group">
                <h6>{{ $t('therapy.lbl_break') }}</h6>
                <div class="col-md-12 row row-cols-3">
                  <flat-pickr id="start_break" class="form-control" v-model="input.start_break" :config="config"></flat-pickr>
                  <flat-pickr id="end_break" class="form-control" v-model="input.end_break" :config="config"></flat-pickr>
                  <div>
                    <a class="btn btn-primary" @click="deleteInputField(day, index)">{{ $t('messages.remove') }}</a>
                  </div>
                </div>
              </div>
              <div>
                <a @click="addInputField(day)" class="clickable-text">
                  <h6><i class="fa fa-plus-circle" aria-hidden="true"></i> {{ $t('therapy.lbl_add_break') }}</h6>
                </a>
              </div>
            </template>
          </div>
        </li>
      </ul>
      <FormFooter :IS_SUBMITED="IS_SUBMITED"></FormFooter>
    </div>
  </form>
</template>

<script setup>
import { ref, onMounted,watchEffect,computed  } from 'vue'
import CardTitle from '@/Setting/Components/CardTitle.vue'

import { THERAPY_CENTER_LIST, LISTING_URL, STORE_URL, THERAPIST_DATA,THERAPY_CENTER_SESSION_LIST,THERAPIST_LIST,EDIT_URL } from '../constant/therapist-session'
import { useModuleId, useRequest, useOnOffcanvasHide } from '@/helpers/hooks/useCrudOpration'
import { useSelect } from '@/helpers/hooks/useSelect'
import FlatPickr from 'vue-flatpickr-component'
import { useForm, useField } from 'vee-validate'
import moment from 'moment'
import * as yup from 'yup'
import FormFooter from '@/vue/components/form-elements/FormFooter.vue'
import FormHeader from '@/vue/components/form-elements/FormHeader.vue'

const singleSelectOption = ref({
  closeOnSelect: true,
  searchable: true,
  clearable: false
})

const time_slot = ref('00:15');
const gettimeslot = () => {
  let timeSlots = [];
  for (let minute = 5; minute <= 60; minute += 5) {
    let minuteString = minute.toString().padStart(2, '0');
    let label = `00:${minuteString}`;
    let value = `00:${minuteString}`;
    timeSlots.push({ label, value });
  }
  let defaultIndex = 2;
  timeSlots[defaultIndex].default = true;
  return timeSlots;
}

const setTimeSlots = (centerMappingData) => {
  if (centerMappingData && centerMappingData.length > 0) {
    time_slot.value = centerMappingData[0].time_slot;
  } else {
    time_slot.value = '';
  }
}

const Title = ref(null)
const Therapist = ref([])

const TherapistId = useModuleId(() => {
  therapist_id.value = TherapistId.value
  getRequest({ url: THERAPIST_DATA, id: TherapistId.value }).then((res) => {
    if (res.data) {
      Therapist.value = res.data
      Title.value = res.data.first_name + ' ' + res.data.last_name + "'s Sessions"
    }
  })

  useSelect({ url: THERAPY_CENTER_LIST, data: TherapistId.value }, { value: 'id', label: 'center_name' }).then((data) => {

    therapy_center.value = data
    if (data.options.length > 0) {
      therapy_center_id.value = data.options[0].value
    }
    getCenterSession(therapy_center_id.value);
    getRequest({ url: LISTING_URL, id: { therapy_center_id: therapy_center_id.value, therapist_id: TherapistId.value } }).then((res) => {
      if (res.status) {
        if (res.data != '') {
          weekdays.value = res.data
          setTimeSlots(res.center_mapping_data);
        } else {
          getCenterSession(therapy_center_id.value);
        }
      }
    })
  })
}, 'therapist_session')

const centerHolidays = ref([]);
const centerStartTime = ref([]);
const centerEndTime = ref([]);
const getCenterSession = () => {
  getRequest({ url: THERAPY_CENTER_SESSION_LIST, id: therapy_center_id.value }).then((res) => {
    if (res.status) {
      if (res.data != '') {
        weekdays.value = res.data;
        centerHolidays.value = res.data.filter(day => day.is_holiday).map(day => day.day); 
        centerStartTime.value = res.data.map(day => day.start_time); 
        centerEndTime.value = res.data.map(day => day.end_time); 
      } else {
        weekdays.value = defaultData();
      }
    }
  });
};

onMounted(() => {
  getCenterSession();
  getTherapistList();
  getTherapyCenterList();
  })

const IS_SUBMITED = ref(false)

const config = ref({
  dateFormat: 'H:i:S',
  altInput: true,
  altFormat: 'h:i K',
  enableTime: true,
  noCalendar: true,
  defaultHour: '09', // Update default hour to 9
  defaultMinute: '00',
  defaultSeconds: '00',
  static: true
})

const { storeRequest, getRequest } = useRequest()

const validationSchema = yup.object({
  therapist_id : yup.number().required('Therapist name is required'),
  therapy_center_id: yup.number().required()
})

const { handleSubmit, errors } = useForm({ validationSchema })

const { value: therapist_id } = useField('therapist_id')
const { value: therapy_center_id } = useField('therapy_center_id')

const therapy_center = ref({ options: [], list: [] })

// message
const display_submit_message = (res) => {
  IS_SUBMITED.value = false
  if (res.status) {
    window.successSnackbar(res.message)
  } else {
    window.errorSnackbar(res.message)
  }
}


const defaultData = () => {
  return [
    { day: 'monday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'tuesday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'wednesday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'thursday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'friday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'saturday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] },
    { day: 'sunday', start_time: moment().set({ hour: 9, minute: 0, second: 0 }).format('HH:mm'), end_time: moment().set({ hour: 18, minute: 0, second: 0 }).format('HH:mm'), is_holiday: false, breaks: [] }
  ]
}
const weekdays = ref(defaultData())

const handleCopy = () => {
  weekdays.value.forEach((day, index) => {
    if (index !== 0) {
      day.start_time = weekdays.value[0].start_time
      day.end_time = weekdays.value[0].end_time
      day.is_holiday = weekdays.value[0].is_holiday
      day.breaks = [...weekdays.value[0].breaks]
    }
  })
}

const therapistlist = ref({ options: [], list: [] })

  //get all therapist
  const getTherapistList = (value) => {
    useSelect({ url: THERAPIST_LIST, data: value }, { value: 'therapist_id', label: 'therapist_name' }).then((data) => {
     therapistlist.value = data;
    })
  }

  //get therapicenter list
  const getTherapyCenterList = (therapiId) => {
    useSelect({ url: THERAPY_CENTER_LIST,data:therapiId}, { value: 'id', label: 'center_name' }).then((data) => {
      therapy_center.value = data
      if (data.options.length > 0) {
        therapy_center_id.value = data.options[0].value
      }
    })
  }

const TherapyCenterSelect = (e) => {
  const TherapyCenterId = therapy_center_id.value
  const Therapist_Id = TherapistId.value
  getCenterSession(TherapyCenterId);
  getRequest({ url: LISTING_URL, id: { therapy_center_id: TherapyCenterId, therapist_id: Therapist_Id } }).then((res) => {
    if (res.status) {
      if (res.data != '') {
        weekdays.value = res.data
        setTimeSlots(res.center_mapping_data);
      } else {
        getCenterSession(TherapyCenterId);
      }
    }
  })
}
watchEffect(() => {
  if (centerStartTime && centerEndTime && centerStartTime.value && centerEndTime.value) {
    weekdays.value.forEach((day, index) => {
      const therapistStartTime = moment(day.start_time, 'HH:mm');
      const therapistEndTime = moment(day.end_time, 'HH:mm');
      const centerStartTimes = moment(centerStartTime.value[index], 'HH:mm');
      const centerEndTimes = moment(centerEndTime.value[index], 'HH:mm');

      delete day.startTimeError;
      delete day.endTimeError;
      if (therapistStartTime.isBefore(centerStartTimes) || therapistStartTime.isAfter(centerEndTimes)) {
        day.startTimeError = `therapist start time for ${day.day} must be between Center operating hours`;
      }

      if (therapistEndTime.isBefore(centerStartTimes) || therapistEndTime.isAfter(centerEndTimes)) {
        day.endTimeError = `therapist end time for ${day.day} must be between Center operating hours`
      }
    });
  }
});
const hasTimeSlotErrors = computed(() => {
  return weekdays.value.some(day => day.startTimeError || day.endTimeError);
});
const breaks = ref([])

const addInputField = (day) => {
  day.breaks.push({ start_break: moment().set({ hour: 0, minute: 0, second: 0 }).format('HH:mm'), end_break: moment().set({ hour: 0, minute: 0, second: 0 }).format('HH:mm') })
}

const deleteInputField = (day, index) => {
  day.breaks.splice(index, 1)
}

//Form Submit
const formSubmit = handleSubmit((values) => {
  IS_SUBMITED.value = true
  if (hasTimeSlotErrors.value) {
    window.errorSnackbar('Please correct the errors before submitting.');
    IS_SUBMITED.value = false
    return;
  }
  values.weekdays = weekdays.value
  values.therapy_center_id = therapy_center_id.value
  values.therapist_id = therapist_id.value
  values.time_slot = time_slot.value
  console.log(values.weekdays);
  storeRequest({ url: STORE_URL, body: values }).then((res) => {
    if (res.status) {
      weekdays.value = res.data
      display_submit_message(res)
      bootstrap.Offcanvas.getInstance('#form-offcanvas').hide()
    }
  })
})
// useOnOffcanvasHide('therapist_change_password', () => setFormData(defaultData()))

</script>
<style>
.multiselect-clear {
  display: none !important;
}
.clickable-text {
  display: inline-block;
  cursor: pointer;
}
.bussiness-hour .data-scrollbar {
  height: 700px;
  overflow-y: auto;
}
.background_colour {
  background-color: #50494917 !important;
  cursor: not-allowed;
}
.copy-icon {
  color: gray;
}
</style>

<style scoped>
@media only screen and (min-width: 768px) {
  .offcanvas {
    width: 80%;
  }
}

@media only screen and (min-width: 1280px) {
  .offcanvas {
    width: 60%;
  }
}
</style>
