export const MODULE = 'therapy-center-session'
export const LISTING_URL = ({therapy_center_id}) => {return {path: `therapy-center-session/index_list?therapy_center_id=${therapy_center_id}`, method: 'GET'}}
export const STORE_URL = () => {return {path: `${MODULE}`, method: 'POST'}}

export const THERAPY_CENTER_DATA = (id) => {return {path: `therapy-centers/${id}/edit`, method: 'GET'}}