<template>
    <form @submit.prevent="formSubmit">
      <div class="offcanvas offcanvas-end" tabindex="-1" id="service-therapist-assign-form" aria-labelledby="form-offcanvasLabel">
        <div class="offcanvas-header border-bottom" v-if="service">
          <h6 class="m-0 h5">
            Service: <span>{{ service.name }}</span>
          </h6>
        </div>
  
        <div class="offcanvas-body">
          <div class="form-group">
            <div class="d-grid">
              <div class="d-flex flex-column">
                <div class="form-group">
                <Multiselect  placeholder="Select Therapy Center" :canClear="true" :value="centers.options" v-bind="centers" @select="selectCenter" id="therapy_center_id">
                  <template v-slot:multiplelabel="{ values }">
                    <div class="multiselect-multiple-label">Select Therapy Center</div>
                  </template>
                </Multiselect>
                
              </div>
              <template v-if="selectedCenter.length > 0">
                <div class="form-group" v-if="therapist.options.length > 0">
                  <Multiselect v-model="assign_ids" placeholder="Select Therapists" :canClear="false" :value="assign_ids" v-bind="therapist" @select="selectTherapist" @deselect="removeTherapist" id="therapist_ids">
                    <template v-slot:multiplelabel="{ values }">
                      <div class="multiselect-multiple-label">Select Therapists</div>
                    </template>
                  </Multiselect>
                </div>
                <div v-else>
                  <p>No doctors available for selected Therapy Center</p>
                </div>
              </template>
               
              </div>
              <div class="list-group list-group-flush" v-if="therapist.options.length > 0">
                <div v-for="(item, index) in selectedTherapist" :key="item" class="list-group-item">
                  <div class="d-flex justify-between align-items-center flex-grow-1 gap-2 mt-2">
                    <span>{{ ++index }} - </span>
                    <div class="d-flex justify-between flex-grow-1 gap-2 my-2">
                    <img :src="item.avatar" class="avatar avatar-40 img-fluid rounded-pill" alt="user" />
                    <div class="flex-grow-1 mt-2"> {{ item.therapist_name }}</div>
                  </div>
                    <button type="button" @click="removeTherapist(item.therapist_id)" class="btn btn-sm text-danger"><i class="fa-regular fa-trash-can"></i></button>
                  </div>
                  <div class="row mb-2">
                   
                    <div class="d-flex justify-content-end align-items-center gap-2 col-6">{{ CURRENCY_SYMBOL }}<input type="number" v-model="item.charges" class="form-control" /></div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
  
        <div class="offcanvas-footer">
          <p class="text-center mb-0"><small>Assign Service To Therapists</small></p>
          <div class="d-grid gap-3 p-3" v-if="therapist.options.length > 0">
            <button class="btn btn-primary d-block" @click="handleUpdate">
            <i class="fa-solid fa-floppy-disk"></i>
            Update
            </button>
          </div>
          <div class="d-grid gap-3 p-3">
            <button class="btn btn-outline-primary d-block" type="button" data-bs-dismiss="offcanvas" @click="handleUpdate">
              <i class="fa-solid fa-angles-left"></i>
              Close
            </button>
          </div>
        </div>
      </div>
    </form>
  </template>
  <script setup>
  import { ref, onMounted } from 'vue'
  import { GET_THERAPIST_ASSIGN_URL, POST_THERAPIST_ASSIGN_URL, EDIT_URL,THERAPY_CENTER_LIST } from '../../constant/therapy-service'
  import { THERAPIST_LIST } from '../../constant/therapy-service'
  import { useModuleId, useRequest } from '@/helpers/hooks/useCrudOpration'
  import { buildMultiSelectObject } from '@/helpers/utilities'
  
  // Request
  const { listingRequest, getRequest, updateRequest } = useRequest()
  
  // Vue Form Select START
  // Select Option
  const therapist = ref({
    mode: 'multiple',
    searchable: true,
    options: []
  })
  const centers = ref({
  mode: 'single',
  searchable: true,
  options: []
})
  const CURRENCY_SYMBOL = ref(window.defaultCurrencySymbol)
  const selectedTherapist = ref([])
  const selectedCenter = ref([])
  // Vue Form Select END
  
  // Form Values
  const assign_ids = ref([])
  const service = ref(null)
  const serviceId = useModuleId(() => {
    getRequest({ url: GET_THERAPIST_ASSIGN_URL, id: serviceId.value }).then((res) => {
      if (res.status && res.data) {
        selectedTherapist.value = res.data
        assign_ids.value = res.data.map((item) => item.therapist_id)
      }
    })
    // getRequest({ url: EDIT_URL, id: serviceId.value }).then((res) => res.status && (service.value = res.data))
    const editFunction = async () => {
    const editRes = await getRequest({ url: EDIT_URL, id: serviceId.value });
    console.log(editRes);
    if (editRes.status && editRes.data && Array.isArray(editRes.data.therapy_center_id) && editRes.data.therapy_center_id.length > 0) {
      service.value = editRes.data;
      const centerIds = editRes.data.therapy_center_id; 
      await fetchTherapyCenterList(centerIds);
    }
  };

  editFunction();
  }, 'therapist_assign')

  const centerList = ref([]);

const fetchTherapyCenterList = async (centerIds) => {
  const requestData = centerIds ? { therapy_center_id: centerIds } : {}; // Check if centerIds is provided
  const res = await listingRequest({ url: THERAPY_CENTER_LIST, data: requestData });
  centerList.value = res;
  centers.value.options = buildMultiSelectObject(res, { value: 'id', label: 'center_name' });
};

const selectCenter = async (value) => {
  const therapyCenter = centerList.value.find((therapyCenter) => therapyCenter.id === value)
  const newCenter = {
    center_name: therapyCenter.center_name,
    id: therapyCenter.id,
  }
  selectedCenter.value = [...selectedCenter.value, newCenter]
  console.log(selectedCenter.value );
  await fetchDoctorList(value);
}
  
  const therapistList = ref([])
  const fetchDoctorList = async (centerIds) => {
  const res = await listingRequest({ url: THERAPIST_LIST, data: { therapy_center_id: centerIds } });
  therapistList.value = res
  therapist.value.options = buildMultiSelectObject(res, { value: 'therapist_id', label: 'therapist_name' })
};
  onMounted(() => {
    fetchTherapyCenterList(therapy_center_id.value);
  })
  
  // Reload Datatable, SnackBar Message, Alert, Offcanvas Close
  const errorMessages = ref([])
  const reset_close_offcanvas = (res) => {
    if (res.status) {
      window.successSnackbar(res.message)
      bootstrap.Offcanvas.getInstance('#service-therapist-assign-form').hide()
      renderedDataTable.ajax.reload(null, false)
    } else {
      window.errorSnackbar(res.message)
      errorMessages.value = res.all_message
    }
  }
  
  const formSubmit = () => {
    const data = { therapist: [] }
    for (let index = 0; index < selectedTherapist.value.length; index++) {
      const element = selectedTherapist.value[index]
      data.therapist.push({
        therapist_name: element.therapist_name,
        therapist_id: element.therapist_id,
        service_id: element.service_id,
        charges: element.charges,
  
      })
    }
    updateRequest({ url: POST_THERAPIST_ASSIGN_URL, id: serviceId.value, body: data }).then((res) => reset_close_offcanvas(res))
  }
  
  const selectTherapist = (value) => {
    const therapists = therapistList.value.find((therapists) => therapists.therapist_id === value)
    const newTherapist = {
      therapist_name: therapists.therapist_name,
      therapist_id: therapists.therapist_id,
      service_id: service.value.id,
      charges: service.value.charges,
      avatar: therapists.avatar,
    }
    selectedTherapist.value = [...selectedTherapist.value, newTherapist]
  }
  
  const removeTherapist = (value) => {
    selectedTherapist.value = [...selectedTherapist.value.filter((therapists) => therapists.therapist_id !== value)]
    assign_ids.value = [...assign_ids.value.filter((id) => id !== value)]
  }
  </script>
  